const veiledDistricts=[[.17,.20],[.50,.133],[.845,.20],[.91,.469],[.836,.761],[.50,.855],[.178,.770],[.093,.469]].map(([x,y],i)=>({id:'veiled-'+(i+1),name:'???',x:x*1800,y:y*1180,area:1000000}));
function veiledWorldNodes(){return veiledDistricts.map((d,i)=>`<div class="veiled-world-district" data-veiled-district="${d.id}" style="left:${d.x/18}%;top:${d.y/11.8}%"><span class="district-fog" aria-hidden="true"></span><button data-veiled-city="${d.id}" aria-label="Unrevealed guild city ${i+1}: ???"><span>???</span><small>IN THE MIST</small></button></div>`).join('')}
communityRegistry.forEach(c=>{const found=baseGuilds.find(x=>x.id===c.id);if(found)Object.assign(found,c);else baseGuilds.push({...c})});
const communityById=id=>communityRegistry.find(c=>c.id===id);const worldGuilds=()=>communityRegistry.map(c=>guildById(c.id));
captains[0].guild='huddle';captains[0].name='Pudgy Captain';captains[0].handle='A SHARED PERSPECTIVE';captains[1].guild='memeland';captains[1].name='Memeland Captain';captains[1].handle='THE CREW’S PERSPECTIVE';captains[2].guild='hilumia';captains[2].name='Hilumia Captain';captains[2].handle='THE CREATIVE PERSPECTIVE';
captains.push({...captains[0],id:'bunny-captain',guild:'bunny',name:'Bunny Captain',handle:'THE CITY’S PERSPECTIVE',roi:16.8,drawdown:10.2,winRate:57.1,trades:164,copiers:96,days:138,color:'gold'});
let preferredMap='collapsed';try{preferredMap=localStorage.getItem('xox-world-display-trader-v1')||'collapsed'}catch{}
const worldUI={mode:preferredMap==='collapsed'?'collapsed':'expanded',selected:null,zoom:1,panX:0,panY:0,drag:null,full:false,tab:'map',space:1800,height:1180};
const plotGeometry={width:450,height:260,points:'0,-130 197,-75 225,52 0,130 -225,52 -197,-75'};
function ownCommunity(){return communityById(state.membership?.id)}
function worldLink(id){return state.membership?.id===id?'my-guild':'guild/'+id}
function communityCard(c){const g=guildById(c.id),own=state.membership?.id===c.id;return `<article class="world-community-card theme-${c.id}"><a class="community-card-art" href="#/${worldLink(c.id)}"><img src="${c.art}" alt="${c.name} community district" loading="lazy"><span class="community-card-category">${escapeHtml(c.community)}</span>${own?'<span class="my-guild-badge">MY GUILD</span>':''}</a><div class="community-card-body"><div><img src="${emblem(g)}" alt=""><div><span>${escapeHtml(c.community)}</span><h3>${escapeHtml(c.name)}</h3></div><button class="bookmark ${state.saved.includes(c.id)?'is-saved':''}" data-save="${c.id}" aria-label="Save ${c.name}" aria-pressed="${state.saved.includes(c.id)}">${icon('bookmark')}</button></div><p>${c.tag}</p><div class="community-card-stats"><span><small>GUILD MEMBERS</small><strong>${g.members.toLocaleString()}</strong></span><span><small>SEASON VOLUME · SAMPLE</small><strong>${numberCompact(seasonVolume(g))}</strong></span></div><a class="community-card-action" href="#/${worldLink(c.id)}">${icon(own?'home':'eye')}${own?'Enter my guild':'Visit guild'} ${arrow()}</a></div></article>`}
function mapWorldScene(){return `<div class="world-scene" id="world-scene" style="--world-z:${worldUI.zoom};--pan-x:${worldUI.panX}px;--pan-y:${worldUI.panY}px"><img src="assets/world-expanded.webp" class="world-environment world-unified-art" width="1536" height="1024" alt="XOX Arena Tower at the centre of a continuous ocean world, surrounded by four revealed communities and eight equally allocated mysterious city districts hidden in mist" draggable="false" loading="lazy" decoding="async" fetchpriority="low">${veiledWorldNodes()}<svg class="world-territories" viewBox="0 0 1800 1180" preserveAspectRatio="none" aria-hidden="true">${[...communityRegistry,...veiledDistricts].map(c=>`<g class="territory-shape ${state.membership?.id===c.id?'mine':''} ${worldUI.selected===c.id?'selected':''}" transform="translate(${c.x} ${c.y})" data-territory="${c.id}"><polygon points="${plotGeometry.points}"/></g>`).join('')}</svg>${communityRegistry.map(c=>`<div class="world-community ${state.membership?.id===c.id?'mine':''}" style="left:${c.x/18}%;top:${c.y/11.8}%" data-map-community="${c.id}"><button class="world-node" data-world-guild="${c.id}" aria-label="${state.membership?.id===c.id?'Enter my guild':'Preview and visit'} ${c.name}"><span class="world-node-emblem"><img src="${emblem(guildById(c.id))}" alt=""></span><span><small>${c.community==='Azuki'?'AZUKI COMMUNITY':c.community==='Pudgy Penguins'?'PUDGY PENGUINS':'COMMUNITY GUILD'}</small><strong>${c.city||c.name}</strong></span>${state.membership?.id===c.id?'<span class="node-my-label">MY GUILD</span>':icon('chevron')}</button><button class="world-district-hit" data-world-guild="${c.id}" aria-label="Explore ${c.name} district" tabindex="-1"></button></div>`).join('')}<a href="#/arena" class="arena-map-node"><span class="arena-node-orbit"></span><span><small>THE SHARED ARENA</small><strong>XOX Arena</strong></span>${arrow()}</a><div class="world-map-watermark">THE COMMUNITY ARCHIPELAGO <span>04 REVEALED · 08 IN THE MIST</span></div></div>`}

function worldSelection(){const c=communityById(worldUI.selected);if(!c)return '';const g=guildById(c.id),own=state.membership?.id===c.id;return `<aside class="world-preview-card" aria-label="${c.name} preview"><button class="preview-card-close" data-clear-map-selection aria-label="Close guild preview">${icon('close')}</button><span class="world-preview-eyebrow">${own?'YOUR TRADING CIRCLE':'EXPLORE A COMMUNITY'}</span><div class="world-preview-identity"><img src="${emblem(g)}" alt=""><div><small>${c.community}</small><h3>${c.name}</h3></div></div><p>${c.tag}</p><div class="world-preview-stats"><span><small>MEMBERS</small><strong>${g.members.toLocaleString()}</strong></span><span><small>GUILD OPEN · SAMPLE</small><strong>#${worldGuilds().sort((a,b)=>b.volume-a.volume).findIndex(x=>x.id===c.id)+1}</strong></span></div><div class="visit-scope">${icon(own?'shield':'eye')} ${own?'Your dashboard, team chat and member features.':'Public overview and leader results. Member features stay private.'}</div><a href="#/${worldLink(c.id)}" class="primary button">${own?'Enter my guild':'Visit guild'} ${arrow()}</a></aside>`}
function guildWorld(){const own=ownCommunity();return `<section class="guild-world ${worldUI.mode==='collapsed'?'is-collapsed':''} ${worldUI.full?'is-fullscreen':''}" id="guild-world" aria-label="Interactive Guild World"><div class="world-topbar"><div class="world-section-brand"><span>${icon('map')}</span><div><h2>GUILD WORLD</h2><small>DIFFERENT COMMUNITIES. ONE SHARED ARENA.</small></div><span class="world-count">04 REVEALED · 08 IN THE MIST</span></div><div class="world-header-controls"><button data-world-toggle aria-expanded="${worldUI.mode!=='collapsed'}" aria-controls="world-explore"><span>${icon(worldUI.mode==='collapsed'?'expand':'minus')}</span>${worldUI.mode==='collapsed'?'Explore world':'Minimize'}</button>${worldUI.mode!=='collapsed'?`<button data-world-full aria-label="${worldUI.full?'Exit full screen':'Explore full screen'}">${icon(worldUI.full?'close':'expand')}</button>`:''}</div></div><div class="world-collapsed-summary" ${worldUI.mode!=='collapsed'?'hidden':''}><div><span class="world-mini-scene"><img src="assets/world-arena.webp" alt=""></span><span>${own?`<small>YOUR COMMUNITY</small><strong>${own.name}</strong>`:'<small>YOUR WORLD IS ONE CLICK AWAY</small><strong>Find your trading circle.</strong>'}</span></div><p>Keep exploring, or go straight to your team and the standings.</p><div>${own?link('my-guild','Enter my guild '+arrow(),'secondary button'):link('discover','Find a guild '+arrow(),'secondary button')}<button class="text-button" data-world-toggle>Open world ${arrow()}</button></div></div><div id="world-explore" ${worldUI.mode==='collapsed'?'hidden':''}><div class="world-viewport" id="world-viewport" tabindex="0" aria-label="Drag to explore the world. Use zoom controls or arrow keys to pan. Select a named community to visit.">${mapWorldScene()}<div class="world-map-grain" aria-hidden="true"></div><div id="world-preview-mount">${worldSelection()}</div><div class="world-location-label">${icon('spark')} ${own?'YOUR COMMUNITY HAS A PLACE HERE':'A WORLD BUILT BY ITS COMMUNITIES'}</div><div class="world-map-tools"><div><button data-map-zoom="in" aria-label="Zoom in">${icon('plus')}</button><button data-map-zoom="out" aria-label="Zoom out">${icon('minus')}</button><button data-map-reset aria-label="Reset map view">${icon('map')}</button></div><button class="world-find-me" data-map-mine>${icon('home')} ${own?'My guild':'Find my guild'}</button></div><div class="world-map-instruction">${icon('map')} Drag to explore <i>·</i> Use + / − to zoom</div></div><div class="world-map-footer"><div><span class="legend-dot mine"></span> My guild <span class="legend-dot community"></span> Visit a community <span class="legend-dot arena"></span> Shared arena</div><span>12 equal territories · 8 identities unrevealed</span></div></div></section>`}
function homeIntro(){return `<div class="guild-home-intro"><div><span class="page-eyebrow"><i></i> XOX GUILDS · THE COMMUNITY ARCHIPELAGO</span><h1>DIFFERENT WORLDS.<br><span>ONE SHARED ARENA.</span></h1><p>Your people. Your perspective. Your place in the climb.</p></div><div class="home-intro-aside"><span>BUILT BY COMMUNITIES.<br>CONNECTED THROUGH COMPETITION.</span>${link(state.membership?'my-guild':'discover',state.membership?'Enter my guild '+arrow():'Find your people '+arrow(),'primary button')}</div></div>`}
function homeBattleFeature(){const g=state.membership&&guildById(state.membership.id),a=g||guildById('huddle'),b=worldGuilds().find(x=>x.id!==a.id);return `<section class="home-battle-editorial"><div class="battle-editorial-copy"><span class="page-eyebrow">GUILD VS GUILD · MATCH PREVIEW</span><h2>Shared ambition.<br><span>A worthy opponent.</span></h2><p>One opponent. A collective effort.<br>Follow the team, and see your part in its progress.</p>${link('arena',g?'Continue your battle '+arrow():'Explore Guild Battle '+arrow(),'text-button')}</div><div class="battle-editorial-versus"><div><img src="${emblem(a)}" alt=""><small>${g?'YOUR GUILD':'COMMUNITY GUILD'}</small><strong>${escapeHtml(a.name)}</strong></div><span>VS</span><div><img src="${emblem(b)}" alt=""><small>THE CHALLENGER</small><strong>${escapeHtml(b.name)}</strong></div><div class="battle-editorial-line"><i></i></div><p>ILLUSTRATIVE PAIRING · NO LIVE MATCH</p></div></section>`}
function homeCommunityDirectory(){return `<section class="world-home-communities"><div class="home-section-header"><div><span class="page-eyebrow">FOUR REVEALED COMMUNITIES. DISTINCT HOMES.</span><h2>Find a world<br><span>that feels like yours.</span></h2></div>${link('discover','Explore the communities '+arrow(),'text-button')}</div><div class="home-community-directory">${communityRegistry.map((c,i)=>`<a href="#/${worldLink(c.id)}" class="directory-community theme-${c.id}"><span class="directory-index">0${i+1}</span><img src="${emblem(guildById(c.id))}" alt=""><span><small>${c.community}</small><strong>${c.name}</strong><em>${c.tag}</em></span><span class="directory-visit">${state.membership?.id===c.id?'Enter my guild':'Visit guild'} ${arrow()}</span></a>`).join('')}</div></section>`}
function worldHome(){return `${homeIntro()}<div id="guild-world-mount">${guildWorld()}</div><div class="world-demo-caption">${icon('info')} Community world concept · All memberships, matches and performance figures are illustrative.</div>${typeof journeyHomePanel==='function'?journeyHomePanel():''}${homeBattleFeature()}<section class="world-home-standings"><div class="home-section-header"><div><span class="page-eyebrow">THE LONG GAME · GUILD OPEN</span><h2>Many communities.<br><span>One collective climb.</span></h2></div>${link('rankings','Full leaderboard '+arrow(),'text-button')}</div><div class="workspace-panel season-standings-panel"><div class="season-panel-top"><div><strong>Season standings</strong><span class="demo-chip">SAMPLE</span></div>${metricTabs()}</div>${primaryRankTable()}<div class="table-foot"><span>Shared competition. Equal community territories.</span><span>Rankings never change land allocation.</span></div></div></section>${homeCommunityDirectory()}<section class="world-home-leaders"><div class="home-section-header"><div><span class="page-eyebrow">THE PEOPLE BEHIND THE PERSPECTIVE</span><h2>Meet the guild leaders.</h2></div><div><p>Public performance. Copying within your own guild.</p>${link('leaders','Explore leader performance '+arrow(),'text-button')}</div></div><div class="captain-grid">${captains.map(captainCard).join('')}</div></section><div class="world-bottom-invitation"><span>${icon('shield')}</span><div><small>THE NEXT CHAPTER COULD BE YOURS.</small><h2>Bring your people. Build your guild.</h2><p>A shared identity. A dedicated home. A place in the world.</p></div><button class="secondary" data-action="create">Create a guild ${arrow()}</button></div>${footer()}`}

seasonHome=worldHome;
seasonRankRows=function(limit=0){const metric=seasonUI.metric;const all=worldGuilds().sort((a,b)=>metric==='efficiency'?seasonVolume(b)/b.members-seasonVolume(a)/a.members:metric==='participation'?b.activity-a.activity:b.volume-a.volume);const arr=limit?all.slice(0,limit):all.filter(g=>g.name.toLowerCase().includes(ui.rankQuery.toLowerCase()));return arr.map(g=>`<tr class="${state.membership?.id===g.id?'my-standing':''}"><td><span class="rank-glyph rank-${all.indexOf(g)+1}">0${all.indexOf(g)+1}</span></td><td><a class="table-guild" href="#/${worldLink(g.id)}"><img src="${emblem(g)}" alt=""><span>${g.name}${state.membership?.id===g.id?'<b class="you-label">YOUR GUILD</b>':''}<small>${communityById(g.id).community} · ${g.members} members</small></span></a></td><td class="season-volume">${metric==='participation'?g.activity+'%':numberCompact(metric==='efficiency'?seasonVolume(g)/g.members:seasonVolume(g))}</td><td class="season-trend">+ ${g.id==='huddle'?'12.4':g.id==='memeland'?'8.1':'6.7'}%</td><td>${link(worldLink(g.id),state.membership?.id===g.id?'Enter '+arrow():'Visit '+arrow(),'row-link')}</td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">No community matches your search.</td></tr>'};
const worldRankingPage=rankingPage;
rankingPage=function(){return worldRankingPage().replace(/<div class="rank-top-three">[\s\S]*?<\/div><div class="workspace-panel season-standings-panel">/,`<div class="rank-top-three">${worldGuilds().sort((a,b)=>b.volume-a.volume).map((g,i)=>`<a href="#/${worldLink(g.id)}"><span class="rank-podium-position">0${i+1}</span><img src="${emblem(g)}" alt=""><div><small>${communityById(g.id).community.toUpperCase()}</small><h2>${g.name}</h2><span>${g.members} members</span></div><strong>${numberCompact(seasonVolume(g))}<small>SEASON VOLUME · SAMPLE</small></strong></a>`).join('')}</div><div class="workspace-panel season-standings-panel">`).replace(`${guilds().length} guilds in this preview`,`${communityRegistry.length} communities in this preview`)};
const previousDiscoveryPage=discoveryPage;
discoveryPage=function(){return breadcrumb('Find your community')+heading('ONE COMMUNITY. ONE GUILD.','FIND YOUR PEOPLE.<br><span>START A SHARED CHAPTER.</span>','Explore the public side of each community before choosing your trading circle.')+`<div class="world-community-grid">${communityRegistry.map(communityCard).join('')}</div><div class="world-visit-note">${icon('eye')} Visits show community introductions, public standings and leader performance. Member chat and copying stay within your own guild.</div>`};
const priorUpdateDiscovery=updateDiscovery;updateDiscovery=function(){if($('#page-results'))priorUpdateDiscovery()};
function communityThemeBanner(c,own=false){return `<section class="community-theme-banner theme-${c.id}"><div class="community-banner-haze"></div><img class="community-banner-art" src="${c.art}" alt="${c.name} community home"><div class="community-banner-content"><span class="page-eyebrow">${own?'YOUR COMMUNITY HOME':'PUBLIC COMMUNITY VISIT'} · ${c.community.toUpperCase()}</span><div><img src="${emblem(guildById(c.id))}" alt=""><h1 tabindex="-1">${c.name}</h1></div><p>${c.tag}</p><span class="community-access-badge">${icon(own?'shield':'eye')} ${own?'Guild member workspace':'Visitor view · Limited access'}</span></div><div class="community-banner-actions">${own?link('my-guild','Enter my guild '+arrow(),'primary button'):state.pending.includes(c.id)?'<span class="member-pill">Demo application saved</span>':`<button class="primary" data-join="${c.id}">Join this guild ${arrow()}</button>`}${link('','Back to Guild World '+icon('map'),'secondary button')}</div></section>`}
const legacyGuildPage=guildPage;
guildPage=function(id,tab='overview'){const c=communityById(id);if(!c)return legacyGuildPage(id,tab);const own=state.membership?.id===id,g=guildById(id),captain=leaderById(c.captain);if(own&&tab==='members')return breadcrumb(`${link('','Guild World')}<span>/</span>${c.name}`)+communityThemeBanner(c,true)+membersPage(g);if(!own&&['members','activity','copy','settings','chat'].includes(tab))return breadcrumb('Visit '+c.name)+communityThemeBanner(c,false)+`<div class="world-member-lock">${icon('lock')}<h2>A space for the team.</h2><p>Member conversations, contribution details and leader copying are available only within your own guild.</p>${link('guild/'+id,'Return to public overview '+arrow(),'secondary button')}</div>`;return breadcrumb(`${link('','Guild World')}<span>/</span>${c.name}`)+communityThemeBanner(c,own)+`<div class="community-visit-layout"><section><div class="workspace-panel community-public-about">${sectionTitle(own?'Your shared identity':'A look inside the community','One community · One guild')}<p>${escapeHtml(c.description)}</p><div class="community-public-metrics"><span><small>GUILD MEMBERS</small><strong>${g.members.toLocaleString()}</strong></span><span><small>SEASON POSITION · SAMPLE</small><strong>#${worldGuilds().sort((a,b)=>b.volume-a.volume).findIndex(x=>x.id===id)+1}</strong></span><span><small>SEASON VOLUME · SAMPLE</small><strong>${numberCompact(seasonVolume(g))}</strong></span></div></div><div class="workspace-panel public-community-notice">${sectionTitle('From the community','Public welcome')}<p>${c.publicAnnouncement}</p><div class="public-notice-signature"><img src="${emblem(g)}" alt=""><span>${c.name}<small>Community concept preview</small></span></div></div><div class="community-visit-rules"><span>${icon('eye')}</span><div><h3>${own?'Your community, your choice.':'Visit, get to know the team, then choose.'}</h3><p>${own?'Use your guild dashboard for team activity, member chat and optional leader copying.':'This public visit shares the community story and leader results. Joining unlocks member access; copying is always a separate choice.'}</p></div></div></section><aside class="workspace-panel public-guild-leader">${sectionTitle('Meet the guild leader','Public performance · Illustrative')}<span class="captain-avatar ${captain.color}">${captain.name.slice(0,1)}</span><h2>${captain.name}</h2><p>${captain.style}</p><div><span>Sample 30D return</span><strong>+${captain.roi}%</strong></div><div><span>Sample max. drawdown</span><strong>${captain.drawdown}%</strong></div>${link('leaders/'+captain.id,'View public performance '+arrow(),'secondary button')}<small>${icon('lock')} ${own?'Configure copying from your guild workspace.':'Leader copying is for this guild’s members.'}</small></aside></div>`};
const priorWorldMyGuild=myGuildPage;
myGuildPage=function(tab='overview',preview=false){const c=!preview&&ownCommunity();let html=priorWorldMyGuild(tab,preview);if(c){html=html.replace(/<section class="profile-hero">[\s\S]*?<\/section>/,communityThemeBanner(c,true));html=html.replace('A place for shared direction',`${c.name} · Shared direction`)}return html};
function saveMapPreference(){try{localStorage.setItem('xox-world-display-trader-v1',worldUI.mode)}catch{}}
function updateWorldMount(){const mount=$('#guild-world-mount');if(mount)mount.innerHTML=guildWorld();syncFullscreen()}
function syncFullscreen(){document.body.classList.toggle('world-fullscreen-open',worldUI.full&&!!$('#guild-world'))}
function clampPan(){worldUI.panX=Math.max(-420,Math.min(420,worldUI.panX));worldUI.panY=Math.max(-280,Math.min(280,worldUI.panY))}
function applyMapTransform(){clampPan();const scene=$('#world-scene');if(scene){scene.style.setProperty('--world-z',worldUI.zoom);scene.style.setProperty('--pan-x',worldUI.panX+'px');scene.style.setProperty('--pan-y',worldUI.panY+'px')}}
function previewWorldGuild(id){if(state.membership?.id===id){if(worldUI.full){worldUI.full=false;syncFullscreen()}navigate('my-guild');return}worldUI.selected=id;document.querySelectorAll('[data-territory]').forEach(el=>el.classList.toggle('selected',el.dataset.territory===id));const mount=$('#world-preview-mount');if(mount)mount.innerHTML=worldSelection()}
function resetWorldView(){worldUI.zoom=1;worldUI.panX=0;worldUI.panY=0;worldUI.selected=null;applyMapTransform();$('#world-preview-mount')?.replaceChildren();document.querySelectorAll('[data-territory]').forEach(el=>el.classList.remove('selected'))}
const worldBaseRoute=renderRoute;
renderRoute=function(scroll=true){worldBaseRoute(scroll);if(routePath&&worldUI.full){worldUI.full=false;syncFullscreen()}if(!routePath){document.title='XOX Guild World — Your people. Your next chapter.';syncFullscreen()}};
const worldGuildRank=guildRank;
guildRank=function(g,metric='volume'){if(!communityById(g.id))return worldGuildRank(g,metric);return worldGuilds().sort((a,b)=>metric==='efficiency'?seasonVolume(b)/b.members-seasonVolume(a)/a.members:metric==='participation'?b.activity-a.activity:b.volume-a.volume).findIndex(x=>x.id===g.id)+1};
// Public visitors cannot switch into another community's member chat.
const priorOpenGuildChat=openGuildChat;
openGuildChat=function(id){const allowed=id==='lounge'||id&&state.membership?.id===id;if(id&&!allowed){toast('Guild chat is available only to that guild’s members.');id='lounge'}priorOpenGuildChat(id)};
currentChatId=function(){const requested=seasonUI.chatGuild||state.membership?.id||'lounge';return requested==='lounge'||requested===state.membership?.id?requested:'lounge'};
const publicSafeChatMount=mountChat;
mountChat=function(preserveDraft=true){publicSafeChatMount(preserveDraft);const select=$('#dock-room');if(select){for(const option of Array.from(select.options))if(option.value!=='lounge'&&option.value!==state.membership?.id)option.remove();select.value=currentChatId()}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-world-toggle')){worldUI.mode=worldUI.mode==='collapsed'?'expanded':'collapsed';if(worldUI.mode==='collapsed')worldUI.full=false;saveMapPreference();updateWorldMount()}if(b.hasAttribute('data-world-full')){worldUI.full=!worldUI.full;worldUI.mode='expanded';saveMapPreference();updateWorldMount()}if(b.dataset.worldGuild)previewWorldGuild(b.dataset.worldGuild);if(b.hasAttribute('data-clear-map-selection')){worldUI.selected=null;$('#world-preview-mount')?.replaceChildren();document.querySelectorAll('[data-territory]').forEach(el=>el.classList.remove('selected'))}if(b.dataset.mapZoom){worldUI.zoom=Math.max(.8,Math.min(1.9,worldUI.zoom+(b.dataset.mapZoom==='in'?.2:-.2)));applyMapTransform()}if(b.hasAttribute('data-map-reset'))resetWorldView();if(b.hasAttribute('data-map-mine')){const own=ownCommunity();if(own){worldUI.zoom=1.7;worldUI.panX=(900-own.x)*.45;worldUI.panY=(590-own.y)*.35;applyMapTransform();worldUI.selected=own.id;const m=$('#world-preview-mount');if(m)m.innerHTML=worldSelection()}else if(state.membership)navigate('my-guild');else{const first=$('#world-viewport [data-world-guild]');first?.focus();toast('Choose a community to visit, or use Find a Guild.')}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-veiled-city]');if(!b||!veiledDistricts.some(d=>d.id===b.dataset.veiledCity))return;open(`<div class="veiled-city-modal"><span class="veiled-modal-icon">${icon('map')}</span><span class="page-eyebrow">AN UNREVEALED COMMUNITY</span><h2>???</h2><p>A city beyond the mist.</p><div class="journey-note">This territory is reserved for a future community concept. Its identity has not been revealed. There is no guild membership, leader performance or competition entry to show yet.</div><div class="modal-actions"><button class="secondary" data-close-flow>Back to the world</button>${link('discover','Visit a revealed community '+arrow(),'primary button')}</div></div>`)});
document.addEventListener('pointerdown',e=>{const v=e.target.closest('#world-viewport');if(!v||e.target.closest('button,a,input,select,.world-preview-card'))return;worldUI.drag={pointer:e.pointerId,x:e.clientX,y:e.clientY,panX:worldUI.panX,panY:worldUI.panY};v.setPointerCapture?.(e.pointerId);v.classList.add('dragging')});
document.addEventListener('pointermove',e=>{const drag=worldUI.drag;if(!drag||e.pointerId!==drag.pointer)return;worldUI.panX=drag.panX+(e.clientX-drag.x);worldUI.panY=drag.panY+(e.clientY-drag.y);applyMapTransform()});
function endWorldDrag(e){if(worldUI.drag?.pointer===e.pointerId){worldUI.drag=null;$('#world-viewport')?.classList.remove('dragging')}}
document.addEventListener('pointerup',endWorldDrag);document.addEventListener('pointercancel',endWorldDrag);
document.addEventListener('wheel',e=>{if(!e.target.closest('#world-viewport')||!(e.ctrlKey||e.metaKey))return;e.preventDefault();worldUI.zoom=Math.max(.8,Math.min(1.9,worldUI.zoom+(e.deltaY<0?.08:-.08)));applyMapTransform()},{passive:false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&worldUI.full&&!modal.open){worldUI.full=false;updateWorldMount();return}if(e.target.id!=='world-viewport')return;const moves={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]};if(moves[e.key]){e.preventDefault();worldUI.panX+=moves[e.key][0];worldUI.panY+=moves[e.key][1];applyMapTransform()}if(e.key==='+'||e.key==='='){e.preventDefault();worldUI.zoom=Math.min(1.9,worldUI.zoom+.2);applyMapTransform()}if(e.key==='-'){e.preventDefault();worldUI.zoom=Math.max(.8,worldUI.zoom-.2);applyMapTransform()}});
renderRoute(false);
